    console_history = _load_terminal_history(historyKey, historyFile, historyLength)
    _set_readline_history(readline, console_history)

    try:
        try:
            value = input(prompt)
        except EOFError:
            return None
        value = str(value)
        current_history = _readline_history(readline)
