                current_history.pop()
            _save_terminal_history(historyKey, current_history, historyFile, historyLength)
            return value[:maxLen]

        _save_terminal_history(historyKey, current_history, historyFile, historyLength)
        return value
    finally:
        _set_readline_history(readline, outside_history)

